package com.sabyeguyz.clinic.resource;
import com.sabyeguyz.clinic.branch.*; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import java.util.List; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/resources") @org.springframework.transaction.annotation.Transactional public class ClinicResourceController {
 private final ClinicResourceRepository repo; private final BranchRepository branches; public ClinicResourceController(ClinicResourceRepository r,BranchRepository b){repo=r;branches=b;}
 public record Request(@NotBlank String branchCode,@NotBlank String code,@NotBlank String name,@NotBlank String type,@NotBlank String status,Boolean active){} public record Response(Long id,String branchCode,String branchName,String code,String name,String type,String status,boolean active){}
 @GetMapping List<Response> list(){return repo.findAllByOrderByName().stream().map(this::out).toList();} @GetMapping("/{id}") Response get(@PathVariable Long id){return out(find(id));}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) Response create(@Valid @RequestBody Request r){String c=norm(r.code());if(repo.findByCode(c).isPresent())throw new IllegalArgumentException("รหัสทรัพยากรซ้ำ");ClinicResource x=new ClinicResource(branch(r.branchCode()),c,r.name().trim(),norm(r.type()),norm(r.status()));applyActive(x,r.active());return out(repo.save(x));}
 @PutMapping("/{id}") Response update(@PathVariable Long id,@Valid @RequestBody Request r){ClinicResource x=find(id);String c=norm(r.code());if(repo.findByCode(c).filter(v->!v.getId().equals(id)).isPresent())throw new IllegalArgumentException("รหัสทรัพยากรซ้ำ");if(!x.getBranch().getCode().equalsIgnoreCase(r.branchCode()))throw new IllegalArgumentException("ไม่อนุญาตให้ย้ายสาขาของทรัพยากร");x.update(c,r.name().trim(),norm(r.type()),norm(r.status()));applyActive(x,r.active());return out(repo.save(x));}
 @PatchMapping("/{id}/activate") Response activate(@PathVariable Long id){ClinicResource x=find(id);x.activate();return out(repo.save(x));} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@PathVariable Long id){ClinicResource x=find(id);x.deactivate();repo.save(x);}
 private ClinicResource find(Long id){return repo.findById(id).orElseThrow(()->new IllegalArgumentException("ไม่พบทรัพยากร"));} private Branch branch(String code){return branches.findByCode(norm(code)).orElseThrow(()->new IllegalArgumentException("ไม่พบสาขา"));} private String norm(String s){return s.trim().toUpperCase();} private static void applyActive(ClinicResource x,Boolean active){if(active!=null){if(active)x.activate();else x.deactivate();}} private Response out(ClinicResource x){return new Response(x.getId(),x.getBranch().getCode(),x.getBranch().getName(),x.getCode(),x.getName(),x.getType(),x.getStatus(),x.isActive());}
}
